      { id: "d4_a3_9", question: "What does 'off-target effect' mean in gene editing?", options: ["Cas9 cutting at unintended genomic sites", "Cas9 failing to cut at all", "Cas9 mutating the host ribosomes", "gRNA degrading inside cytoplasm"], answer: "Cas9 cutting at unintended genomic sites" },
      { id: "d4_a3_10", question: "Which Cas9 variant creates single-strand nicks instead of double-strand cuts?", options: ["Cas9 Nickase", "dCas9 (dead Cas9)", "Cas12a", "Cas13"], answer: "Cas9 Nickase" }
