    const shuffled = [...db].sort(() => 0.5 - Math.random());
    const selected = shuffled.slice(0, 3).map(item => ({
      ...item,
      options: [...item.options].sort(() => 0.5 - Math.random())
    }));

    setDokQuizzes(prev => ({
      ...prev,
      [`${key}_variants`]: selected,
      [`${key}_answers`]: { 0: "", 1: "", 2: "" },
      [`${key}_correctness`]: { 0: null, 1: null, 2: null },
      [`${key}_completed`]: false
    }));

